class Solution {

    public int trap(int[] height) {
        int n = height.length;
        if (n == 0) return 0;
        int[] pre = new int[n],
            suf = new int[n];
        pre[0] = height[0];
        for (int i = 1; i < n; i++) pre[i] = Math.max(
            pre[i - 1],
            height[i]
        );
        suf[n - 1] = height[n - 1];
        for (int i = n - 2; i >= 0; i--) suf[i] = Math.max(
            suf[i + 1],
            height[i]
        );
        int total = 0;
        for (int i = 0; i < n; i++) total +=
            Math.min(pre[i], suf[i]) - height[i];
        return total;
    }
}

