class Solution {

    public void sortColors(int[] nums) {
        int low = 0,
            mid = 0,
            high = nums.length - 1;
        while (mid <= high) {
            if (nums[mid] == 0) {
                swap(nums, low++, mid++); // 0 goes to the front region
            } else if (nums[mid] == 1) {
                mid++; // 1 is already in the middle region
            } else {
                swap(nums, mid, high--); // 2 goes to the back; recheck nums[mid]
            }
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}

