class Solution {

    public void nextPermutation(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        TreeSet<List<Integer>> all = new TreeSet<>((a, b) -> {
            for (int i = 0; i < a.size(); i++) if (
                !a.get(i).equals(b.get(i))
            ) return a.get(i) - b.get(i);
            return 0;
        });
        permute(sorted, 0, all); // all distinct permutations, ordered
        List<Integer> cur = new ArrayList<>();
        for (int x : nums) cur.add(x);
        List<Integer> next = all.higher(cur);
        if (next == null) next = all.first(); // wrap to smallest
        for (int i = 0; i < nums.length; i++) nums[i] = next.get(i);
    }

    private void permute(int[] a, int k, TreeSet<List<Integer>> out) {
        if (k == a.length) {
            List<Integer> p = new ArrayList<>();
            for (int x : a) p.add(x);
            out.add(p);
            return;
        }
        for (int i = k; i < a.length; i++) {
            int t = a[k];
            a[k] = a[i];
            a[i] = t;
            permute(a, k + 1, out);
            t = a[k];
            a[k] = a[i];
            a[i] = t;
        }
    }
}

