var nextPermutation = function (nums) {
    const perms = new Set();
    const a = [...nums];
    const permute = (k) => {
        if (k === a.length) {
            perms.add(a.join(","));
            return;
        }
        for (let i = k; i < a.length; i++) {
            [a[k], a[i]] = [a[i], a[k]];
            permute(k + 1);
            [a[k], a[i]] = [a[i], a[k]];
        }
    };
    permute(0);
    const cmp = (x, y) => {
        for (let i = 0; i < x.length; i++)
            if (x[i] !== y[i]) return x[i] - y[i];
        return;
        0;
    };
    const list = [...perms]
        .map((s) => s.split(",").map(Number))
        .sort(cmp);
    const idx = list.findIndex((p) => cmp(p, nums) === 0);
    const next = list[(idx + 1) % list.length]; // wrap to smallest
    for (let i = 0; i < nums.length; i++) nums[i] = next[i];
};

