class Solution {

    public void nextPermutation(int[] nums) {
        int n = nums.length,
            i = n - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--; // find pivot
        if (i >= 0) {
            int j = n - 1;
            while (nums[j] <= nums[i]) j--; // smallest value bigger than pivot
            swap(nums, i, j);
        }
        reverse(nums, i + 1, n - 1); // suffix becomes ascending
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }

    private void reverse(int[] a, int l, int r) {
        while (l < r) swap(a, l++, r--);
    }
}

