class Solution {

    public void merge(int[] a, int[] b) {
        int n = a.length,
            m = b.length,
            len = n + m;
        int gap = (len + 1) / 2; // ceil(len / 2)
        while (gap > 0) {
            for (
                int left = 0, right = gap;
                right < len;
                left++, right++
            ) {
                if (get(a, b, left) > get(a, b, right)) {
                    int t = get(a, b, left);
                    set(a, b, left, get(a, b, right));
                    set(a, b, right, t);
                }
            }
            if (gap == 1) break;
            gap = (gap + 1) / 2; // ceil(gap / 2)
        }
    }

    // treat a followed by b as one virtual array
    private int get(int[] a, int[] b, int p) {
        return p < a.length ? a[p] : b[p - a.length];
    }

    private void set(int[] a, int[] b, int p, int v) {
        if (p < a.length) a[p] = v;
        else b[p - a.length] = v;
    }
}

