// JS has no built-in heap; a small binary max-heap on [value, index]
var maxSlidingWindow = function (nums, k) {
    const heap = [];
    const less = (a, b) => heap[a][0] < heap[b][0];
    const swap = (a, b) => {
        [heap[a], heap[b]] = [heap[b], heap[a]];
    };
    const push = (x) => {
        heap.push(x);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (!less(p, i)) break;
            swap(p, i);
            i = p;
        }
    };
    const pop = () => {
        const last = heap.pop();
        if (heap.length === 0) return;
        heap[0] = last;
        let i = 0;
        while (true) {
            const l = 2 * i + 1,
                r = l + 1;
            let big = i;
            if (l < heap.length && less(big, l)) big = l;
            if (r < heap.length && less(big, r)) big = r;

            if (big === i) break;
            swap(i, big);
            i = big;
        }
    };
    const res = [];
    for (let i = 0; i < nums.length; i++) {
        push([nums[i], i]);
        while (heap[0][1] <= i - k) pop();
        if (i >= k - 1) res.push(heap[0][0]);
    }
    return res;
};

