class Solution {

    public int numSubarraysWithSum(int[] nums, int goal) {
        return atMost(nums, goal) - atMost(nums, goal - 1);
    }

    // number of subarrays with sum <= g
    private int atMost(int[] nums, int g) {
        if (g < 0) return 0;
        int left = 0,
            sum = 0,
            count = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (sum > g) sum -= nums[left++];
            count += right - left + 1; // all subarrays ending at right starting in [left, right]
        }
        return count;
    }
}

